CHARACTERS={
    '리츠':'RITS','케이':'KEI','어썰트워리어':'ASSAULT WARRIOR',
    '디스럽터':'DISRUPTOR','건슬링어':'GUNSLINGER','나이트템플러':'KNIGHT TEMPLAR',
    '크레이지암즈':'CRAZY ARMS','버서커':'BERSERKER','데스나이트':'DEATH KNIGHT',
    '섀도우워커':'SHADOW WALKER','가디언나이트':'GUARDIAN KNIGHT','소울마스터':'SOUL MASTER','':'',
}


def main():
    entries=[];counts={}
    for filename,copy in ROWS.items():
        rel='res/dat/'+filename
        source=parse((ROOT/'work/original'/rel).read_bytes(),4,rel)
        rows=[line.split('|') for line in copy.strip().splitlines()]
        if len(rows)!=len(source):raise ValueError(f'{filename}: row count {len(rows)} != {len(source)}')
        counts[rel]=4
        for i,((original,tail),translated) in enumerate(zip(source,rows)):
            assert not tail and len(translated)==4
            for field,(s,t) in enumerate(zip(original,translated)):
                t=latin_copy(t,s)
                if field==1:t=';'.join(textwrap.wrap(t,28,break_long_words=False,break_on_hyphens=False))
                entries.append({'id':f'{rel}#{i}.{field}','file':rel,'record':i,'field':field,'source':s,'translation':t})
    rel='res/dat/char_dat';counts[rel]=2
    for i,(texts,_) in enumerate(parse((ROOT/'work/original'/rel).read_bytes(),2,rel)):
        for field,s in enumerate(texts):
            entries.append({'id':f'{rel}#{i}.{field}','file':rel,'record':i,'field':field,'source':s,'translation':CHARACTERS[s]})
    cat={'format':'hl3-prefixed-record-text-v1','encoding':'cp949','field_counts':counts,'entries':entries}
    path=ROOT/'translations/record-text.json'
    path.write_text(json.dumps(cat,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(f'Curated {len(entries)} fields: 154 quest records and 16 character records.')


if __name__=='__main__':main()
